from math import comb

def ratio_Kn(n):
    if n < 4:
        return 0
    f = comb(n, 3)
    g = comb(n, 4)
    return (g**3) / (f**4)

r7 = ratio_Kn(7)
print(f"Ratio for K_7: {r7}")
